import{_ as n,o as s,c as e,ai as l}from"./chunks/framework.BxxKhjs3.js";const h=JSON.parse('{"title":"21-Lambda 表达式","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/21-Lambda 表达式/21-Lambda 表达式.md","filePath":"仓颉入门到实战/21-Lambda 表达式/21-Lambda 表达式.md","lastUpdated":1735131334000,"__rawMarkdown":"# 21-Lambda 表达式\\n\\n## 介绍\\n\\nLambda表达式可以看成是一种函数的简写，对于函数而言，有函数声明、函数调用。所以我们在学习 Lambda表达式的时候也可以从这\\n\\n个作为入手来学习，其中，Lambda表达式特别灵活，在学习的时候尤为注意。\\n\\n## 基本语法\\n\\nLambda 表达式的语法为如下形式： `{ p1: T1, ..., pn: Tn => expressions | declarations }`\\n\\n1. Lambda 表达式 的外层通过 `{}` 来表示\\n2. `=>`  左侧为参数部分\\n3. `=>` 右侧为返回值或者逻辑代码部分\\n\\n\\n\\n## 简单声明\\n\\n```\\n    // 声明  f1 的形参是a，a的类型是Int64 , 返回值 是 a+100\\n    let f1 = {a: Int64 => a + 100}\\n```\\n\\n## 简单调用\\n\\n```\\n\\tprintln(f1(200)) // 将f1 当成函数来调用\\n```\\n\\n## 省略参数类型\\n\\nLambda 表达式 在声明了类型的同时，可以省略形参的类型\\n\\n```\\n    // 没有省略\\n    let f1: (a: Int64) -> Int64 = {a: Int64 => a}\\n    // 省略\\n    let f2: (a: Int64) -> Int64 = {a => a}\\n```\\n\\n## 没有形参\\n\\nLambda 表达式 在没有形参时，写法如下\\n\\n```\\n    // 有参数\\n    let f3 = {a: Int64 => a + 100}\\n    // 没有参数\\n    let f4 = {=> 100}\\n```\\n\\n## 没有返回值\\n\\nLambda 表达式 在没有返回值时，写法如下\\n\\n```\\n    // 没有返回值  也没有形参\\n    let f5 = { => }\\n```\\n\\n## 立即调用\\n\\nLambda 表达式支持立即调用，例如：\\n\\n```\\n    let f6 = {a: Int64, b: Int64 => a + b}(1, 2)\\n    println(f6) // 3\\n    \\n    let f7 = {=> 123}()\\n    println(f7) // 123\\n```\\n\\n## 当成变量进行传递和调用\\n\\n```\\n    func f() {\\n        var g = { x: Int64 => println(\\"x = ${x}\\") }\\n        g(2)\\n    }\\n```\\n\\n"}'),p={name:"仓颉入门到实战/21-Lambda 表达式/21-Lambda 表达式.md"};function i(t,a,r,d,c,b){return s(),e("div",null,[...a[0]||(a[0]=[l("",25)])])}const m=n(p,[["render",i]]);export{h as __pageData,m as default};
